<template>
  <!-- eslint-disable vue/no-v-html -->
  <i
    class="c-icon"
    :class="[size ? `c-icon--${size}` : '']"
    v-html="svgContent"
  />
</template>

<script setup lang="ts">
/**
 * AppIcon
 * feather-iconsを使用したアイコンを表示するコンポーネントです。
 */
import { computed } from "vue";
import feather from "feather-icons";

const props = defineProps<{
  name: string;
  size?: "sm" | "md" | "lg" | "xl";
}>();

const svgContent = computed(() => {
  if (feather.icons[props.name as keyof typeof feather.icons]) {
    // Return raw SVG string generated by feather-icons
    return feather.icons[props.name as keyof typeof feather.icons].toSvg();
  }
  return "";
});
</script>

<style scoped lang="scss">
.c-icon {
  // --- レイアウト・配置 ---
  @include flex-center(0, inline-flex);

  // --- 疑似クラス ---
  :deep(svg) {
    // --- ボックスモデル ---
    width: 100%;
    height: 100%;
  }

  // --- モディファイア ---
  &--sm {
    // --- ボックスモデル ---
    width: 14px;
    height: 14px;
  }
  
  &--md {
    // --- ボックスモデル ---
    width: 18px;
    height: 18px;
  }
  
  &--lg {
    // --- ボックスモデル ---
    width: 24px;
    height: 24px;
  }
  
  &--xl {
    // --- ボックスモデル ---
    width: 32px;
    height: 32px;
  }
}
</style>
